 employee_id uuid not null references public.employees(id), starts_at timestamptz not null, ends_at timestamptz not null, break_minutes integer not null default 0 check(break_minutes>=0), department_snapshot text not null check(department_snapshot in ('SX','VP','BH')), status text not null default 'draft' check(status in ('draft','posted','reversed')), check(ends_at>starts_at and ends_at-starts_at<=interval '24 hours'), check(extract(epoch from(ends_at-starts_at))/60>break_minutes), unique(employee_id,starts_at),
 version bigint not null default 1 check(version>0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references auth.users(id), updated_by uuid references auth.users(id)
);
alter table public.attendance_shifts enable row level security;
create policy attendance_shifts_read on public.attendance_shifts for select to authenticated using((select private.can('attendance','view')));
create trigger attendance_shifts_audit before insert or update or delete on public.attendance_shifts for each row execute function private.record_change('attendance');
grant select on public.attendance_shifts to authenticated;
revoke all on public.attendance_shifts from anon;
